function bonusSources(key){var out=[];["weapon","armor","companion"].forEach(function(slot){var it=get(s.gear[slot]);if(it&&it.effects&&Number(it.effects[key]))out.push({name:it.name,amount:Number(it.effects[key]),kind:"EQUIPPED "+slot.toUpperCase()})});(D.relicCatalog||[]).forEach(function(r){if(s.relics.indexOf(r.id)>=0&&r.effects&&Number(r.effects[key]))out.push({name:r.name,amount:Number(r.effects[key]),kind:"PERMANENT RELIC"})});s.activePotions.forEach(function(p){if(p.effect&&Number(p.effect[key]))out.push({name:p.name,amount:Number(p.effect[key]),kind:p.kind==="timed"?"ACTIVE POTION · TIMED":"ACTIVE POTION · WALKING STEPS"})});return out}
